CREATE TABLE IF NOT EXISTS signal_research (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        entry_time TEXT,
        exit_time TEXT,
        code TEXT,
        name TEXT,
        entry_price REAL,
        last_price REAL,
        setup_quality TEXT,
        change_rate REAL,
        strength REAL,
        trading_value REAL,
        change_rate_bucket TEXT,
        strength_bucket TEXT,
        trading_value_bucket TEXT,
        momentum_efficiency REAL,
        theme_score REAL,
        matched_themes TEXT,
        rule_version TEXT,
        ret_5m REAL,
        ret_10m REAL,
        ret_30m REAL,
        max_return_30m REAL,
        min_return_30m REAL,
        first_touch TEXT,
        first_touch_time TEXT,
        first_touch_return REAL
    );
